// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(this).balance);
        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), amount);
        attacker.deposit{value: amount}();
        uint balanceBefore = address(c).balance;
        attacker.attack();
        uint balanceAfter = address(c).balance;
        assertTrue(balanceBefore - balanceAfter == amount);
    }
}

contract Attacker {
    ReentrancyDAO target;
    bool reentered;
    uint myDeposit;

    constructor(ReentrancyDAO _target) {
        target = _target;
    }

    function deposit() external payable {
        myDeposit = msg.value;
        target.deposit{value: msg.value}();
    }

    function attack() external {
        target.withdrawAll();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            target.withdrawAll();
        }
    }
}
